# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-first finite-state controller with confirmation, hysteretic
    steering, and bounded alternating reacquisition scans.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")
    last_bearing = float(memory.get("last_bearing", 0.0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        memory["last_bearing"] = bearing if visible else last_bearing
        return action, confidence, memory

    # Safety is an unconditional gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    # Require a confirmed target before making progress.
    confirmed = visible and target_confidence >= 0.55 and identity_confidence >= 0.60
    if not confirmed:
        if lost_steps <= 1 and (state in {"LOCKED", "APPROACH", "VERIFY", "ARRIVED"} or lost_steps > 0):
            return emit("STOP", 0.92, "REACQUIRE")

        # Hold one scan direction for several frames to avoid oscillatory commands.
        if lost_steps > 1 and lost_steps % 3 == 0:
            scan_direction = "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = scan_direction
        return emit(scan_direction, 0.75, "SEARCH")

    # A newly acquired track is observed briefly before advancing.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    memory["scan_direction"] = scan_direction
    memory["state"] = "LOCKED"

    if distance == "near":
        if heading_error <= 15.0 and abs(bearing) <= 16.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        if bearing < -10.0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.88, "APPROACH")
        if bearing > 10.0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.88, "APPROACH")
        if heading_error <= 18.0 and observation["corridor_center"]:
            return emit("SLOW_DOWN", 0.86, "APPROACH")

    # Hysteresis keeps small bearing noise from causing left/right flip-flops.
    steer_limit = 15.0
    if last_action == "VEER_LEFT" and bearing < steer_limit:
        steer_limit = 19.0
    elif last_action == "VEER_RIGHT" and bearing > -steer_limit:
        steer_limit = 19.0

    if bearing < -steer_limit and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing > steer_limit and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.90, "APPROACH")
    if observation["corridor_center"]:
        return emit("FORWARD", 0.90, "APPROACH")
    if bearing < 0.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if bearing > 0.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.82, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
